const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const crypto = require('crypto');

class ConnectionPool {
  constructor(maxSize = 10, idleTimeoutMs = 30000) {
    this.maxSize = maxSize;
    this.idleTimeoutMs = idleTimeoutMs;
    this.pool = new Map();
    this.refCounts = new Map();
    this.disposalQueue = [];
    this.gcInterval = setInterval(() => this._gcCycle(), 5000);
  }

  acquire(endpoint) {
    const key = this._makeKey(endpoint);
    if (this.pool.has(key)) {
      const conn = this.pool.get(key);
      if (conn.disposed) {
        this.pool.delete(key);
        this.refCounts.delete(key);
      } else {
        this.refCounts.set(key, (this.refCounts.get(key) || 0) + 1);
        conn.lastAccess = Date.now();
        return conn;
      }
    }
    const conn = this._createConnection(endpoint);
    conn.poolKey = key;
    conn.lastAccess = Date.now();
    conn.disposed = false;
    this.pool.set(key, conn);
    this.refCounts.set(key, 1);
    return conn;
  }

  release(conn) {
    const key = conn.poolKey;
    if (!this.refCounts.has(key)) return;
    const newCount = this.refCounts.get(key) - 1;
    if (newCount <= 0) {
      this.refCounts.set(key, 0);
      this._scheduleDisposal(key);
    } else {
      this.refCounts.set(key, newCount);
    }
  }

  _scheduleDisposal(key) {
    // Deduplicate: only schedule if not already queued
    if (!this.disposalQueue.some(item => item.key === key)) {
      this.disposalQueue.push({ key, scheduledAt: Date.now() });
    }
  }

  _gcCycle() {
    const now = Date.now();
    const pending = [];
    for (const item of this.disposalQueue) {
      if (now - item.scheduledAt >= this.idleTimeoutMs) {
        this._disposeConnection(item.key);
      } else {
        pending.push(item);
      }
    }
    this.disposalQueue = pending;
  }

  _disposeConnection(key) {
    const conn = this.pool.get(key);
    if (!conn || conn.disposed) return;
    // Check refCount before disposing - if re-acquired, skip disposal
    const currentRefs = this.refCounts.get(key) || 0;
    if (currentRefs > 0) return;
    conn.channel.close();
    conn.disposed = true;
    this.pool.delete(key);
    this.refCounts.delete(key);
  }

  _createConnection(endpoint) {
    const channel = new grpc.Channel(
      endpoint,
      grpc.credentials.createInsecure(),
      { 'grpc.max_reconnect_backoff_ms': 5000 }
    );
    return { channel, endpoint };
  }

  _makeKey(endpoint) {
    return crypto.createHash('sha256').update(endpoint).digest('hex').slice(0, 16);
  }

  shutdown() {
    clearInterval(this.gcInterval);
    for (const [key, conn] of this.pool) {
      if (!conn.disposed) {
        conn.channel.close();
        conn.disposed = true;
      }
    }
    this.pool.clear();
    this.refCounts.clear();
  }
}

class GrpcService {
  constructor(protoPath, serviceName) {
    this.pool = new ConnectionPool(10, 5000);
    this.protoPath = protoPath;
    this.serviceName = serviceName;
    this.packageDef = protoLoader.loadSync(protoPath, {
      keepCase: true,
      longs: String,
      enums: String,
      defaults: true,
      oneofs: true
    });
    this.grpcObject = grpc.loadPackageDefinition(this.packageDef);
  }

  async callUnary(endpoint, method, request, metadata = {}) {
    const conn = this.pool.acquire(endpoint);
    return this._executeCall(conn, method, request, metadata);
  }

  async _executeCall(conn, method, request, metadata) {
    if (conn.disposed) {
      throw new Error('Connection disposed before use');
    }
    const client = new this.grpcObject[this.serviceName](
      conn.endpoint,
      grpc.credentials.createInsecure()
    );
    const meta = new grpc.Metadata();
    for (const [k, v] of Object.entries(metadata)) {
      meta.set(k, v);
    }
    return new Promise((resolve, reject) => {
      client[method](request, meta, (err, response) => {
        this.pool.release(conn);
        if (err) reject(err);
        else resolve(response);
      });
    });
  }

  async callWithRetry(endpoint, method, request, metadata = {}, retries = 3) {
    for (let i = 0; i < retries; i++) {
      try {
        return await this.callUnary(endpoint, method, request, metadata);
      } catch (err) {
        if (i === retries - 1) throw err;
        await new Promise(r => setTimeout(r, 100 * (i + 1)));
      }
    }
  }

  shutdown() {
    this.pool.shutdown();
  }
}

module.exports = { ConnectionPool, GrpcService };
